saved program: True from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    foreground = Counter(v for row in grid for v in row if v != background).most_common(1)[0][0]
    row_counts = [sum(value == foreground for value in row) for row in grid]
    stripe_rows = {y for y, count in enumerate(row_counts) if count == max(row_counts)}
    for y in range(1, h - 1):
        if y not in stripe_rows:
            continue
        x = 0
        while x < w:
            if grid[y][x] != background:
                x += 1
                continue
            start = x
            while x < w and grid[y][x] == background:
                x += 1
            end = x - 1
            if start == 0 or end == w - 1 or (end - start + 1) % 2 == 0:
                continue
            c = (start + end) // 2
            if grid[y - 1][c] != foreground:
                continue
            if not any(0 <= c-d and c+d < w and grid[y+1][c-d] == foreground and grid[y+1][c+d] == foreground for d in range(1, min(c, w-1-c) + 1)):
                continue
            stop = next((r for r in range(y + 1, h) if grid[r][c] == foreground), h)
            for r in range(y, stop):
                if out[r][c] == background:
                    out[r][c] = 4
    return out
